/* Shared local prototype: two tasks, a personal space and explicit account demos. */
'use strict';
const taskCatalog = {
  site: {title:'做一个个人网站',short:'个人网站',art:'01-adventure-hall',intro:'把你的故事、兴趣和愿意分享的经验，放在一个可以打开的网页里。',deliverable:'一个可打开的个人网站链接，加上简短的作品说明。',steps:['准备自我介绍、头像和想分享的内容。','用 WorkBuddy 做出第一版网页，检查手机上的阅读和按钮。','请一位伙伴试用，根据具体反馈再改一处。'],checks:['别人能打开网站','能看出我是谁、正在做什么','记录一次试用或修改'],resources:[0,1,2],source:'https://bytedance.feishu.cn/docx/VdIIdBIN9oe9kfxrT9ocye8YnKd'},
  knowledge: {title:'建立个人知识库',short:'个人知识库',art:'03-knowledge-scroll',intro:'从这次课程的记录开始，把零散信息整理成以后找得到、用得上的笔记。',deliverable:'一份整理成果说明，可附可分享的知识库或笔记链接。',steps:['选一份可以整理的课堂记录、学习材料或自己的笔记。','用 AI 辅助提炼主题，回到原记录核对内容，保留来源。','保存到自己的知识库，用清楚的标题和分类让下次能找到。'],checks:['能找到一份已整理的笔记','保留来源并核对了内容','能说明这些记录对自己有什么用'],resources:[5],source:'https://xcnby8ujkwmv.feishu.cn/docx/Dnr9dc7aWot8h1xY1UucDrvhn6g'}
};
if (!saved.knowledge || !Array.isArray(saved.knowledge.versions)) saved.knowledge={draft:{},versions:[],feedback:[]};
saved.knowledge.feedback ||= [];
saved.knowledge.draft ||= {};
saved.demoAccount ||= {signedIn:true,phone:'',email:''};
const taskRecord = id => id==='knowledge' ? saved.knowledge : saved;
const taskState = id => taskRecord(id).versions.length ? '已提交' : Object.values(taskRecord(id).draft).some(Boolean) ? '草稿' : '未提交';
const submittedTasks = () => Object.keys(taskCatalog).filter(id=>taskRecord(id).versions.length).length;
function safeLink(value){try{const u=new URL(String(value));return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function localSave(mutator){const previous=JSON.stringify(saved);mutator();if(persist())return true;saved=JSON.parse(previous);return false;}
const avatarIsValid = value => typeof value==='string' && /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value);
function myAvatar(cls=''){return avatarIsValid(saved.profile.avatar)?`<img class="member-avatar ${cls}" src="${saved.profile.avatar}" alt="" width="80" height="80">`:`<span class="member-avatar initials ${cls}" aria-hidden="true">${esc(Array.from(saved.profile.name||'我')[0])}<i>✦</i></span>`;}
navs[5][2]='我的'; navs[3][2]='广场'; navs[4][2]='伙伴';
weeks[0]=['相识与表达','个人网站与个人知识库','认识新伙伴，做一个个人网站，并开始积累自己的知识库。','为自己做'];
journeyStops[0].artifact='个人网站 + 个人知识库';
journeyStops[0].deliverable='两项任务各自提交、各自收到反馈。';
guideTips[0]={text:'有课程或制作方面的问题，可以向学习伙伴或助教提问。',label:'认识学习伙伴',page:'people'};
guideTips[2]={text:'先留下一版，再根据伙伴的建议改。每次修改都值得记下来。',label:'查看我的任务',page:'profile'};
resources.push({id:5,title:'从一份记录开始建知识库',desc:'整理、核对、保留来源，让下一次查找更容易。',type:'数据与知识库',level:'入门',time:'按自己的节奏',pixel:'book',steps:taskCatalog.knowledge.steps,prompt:'请帮我整理下面的学习记录。按主题提炼要点，保留具体事实和原始来源，区分记录中的事实与我的想法。不要编造记录中没有的信息，不确定的地方单独列出供我核对。最后给出一个清楚的笔记标题和少量便于查找的标签。\n\n学习记录：【粘贴可使用的材料】\n来源与日期：【填写】'});
const pageNames={home:'冒险大厅',map:'八周旅程',resources:'锦囊小屋',gallery:'广场',people:'广场 · 伙伴',profile:'个人中心',friends:'我的好友',account:'账户设置',login:'登录演示'};
let lastOrdinaryRoute='home', taskOrigin='week/1';
const validRoute = route => Object.hasOwn(pageNames,route)||/^week\/[1-8]$/.test(route)||/^(task|submit|work)\/(site|knowledge)$/.test(route);
const routeParent = route => ['account','login','friends'].includes(route)?'profile':route==='people'?'gallery':/^(week|task|submit|work)\//.test(route)?'map':route;
const routeName = route => pageNames[route] || (route.startsWith('week/')?`W${route.split('/')[1]} · 本周任务`:taskCatalog[route.split('/')[1]]?.title||'冒险大厅');
function navMarkup(){const short={home:'大厅',map:'旅程',resources:'锦囊',gallery:'广场',profile:'我的'};return navs.filter(([id])=>id!=='people').map(([id,,label])=>`<button data-page="${id}" class="${routeParent(page)===id?'active':''}" ${routeParent(page)===id?'aria-current="page"':''} aria-label="${label}" title="${label}">${id==='profile'?myAvatar('nav-avatar'):navigationIcon(id)}<span class="nav-full">${label}</span><span class="nav-short">${short[id]}</span></button>`).join('');}
function themeMarkup(){const blue=location.pathname.includes('/bright/');return `<nav class="theme-swatches" aria-label="界面配色"><a class="theme-swatch theme-warm" href="${blue?'../':'./'}index.html?v=20261029-smooth1${location.hash||'#home'}" aria-label="暖色主题" title="暖色主题" ${!blue?'aria-current="true"':''}></a><a class="theme-swatch theme-blue" href="${blue?'./':'bright/'}index.html?v=20261029-smooth1${location.hash||'#home'}" aria-label="蓝色主题" title="蓝色主题" ${blue?'aria-current="true"':''}></a></nav>`;}
shell=function(){return `<div class="shell"><aside class="sidebar"><div class="brand-row"><a href="#home" class="brand brand-text-only" aria-label="AI Builder School 首页"><span class="brand-name">AI BUILDER<br><span>SCHOOL</span></span></a>${themeMarkup()}</div><nav class="nav" aria-label="主导航">${navMarkup()}</nav></aside><div class="compact-navigation" inert aria-hidden="true"><div class="compact-navigation-inner"><div class="brand-row"><a href="#home" class="brand brand-text-only" aria-label="AI Builder School 首页"><span class="brand-name">AI BUILDER<br><span>SCHOOL</span></span></a>${themeMarkup()}</div><nav class="nav" aria-label="主导航">${navMarkup()}</nav></div></div><main class="main"><div class="page" id="page-content"></div><footer class="footer"><span>作品与资料仅保存在此浏览器</span><span>AI BUILDER SCHOOL · 2026</span></footer></main></div>`;};
function go(route,{replace=false,fromHistory=false}={}){
 if(!validRoute(route))route='home';
 if(page==='map')rememberMap();
 if(route!=='friends')friendViewer='self';
 if(route==='map' && page!=='map' && !/^(week|task|submit|work)\//.test(page)){mapOrigin=page;mapSession.intro=true;}
 if(route.startsWith('task/')&&!fromHistory&&!/^(submit|work)\//.test(page))taskOrigin=page==='map'?'map':'week/1';
 if(page!=='map')lastOrdinaryRoute=page;
 closeModal();
 page=route;
 if(!fromHistory)history[replace?'replaceState':'pushState'](null,'','#'+route);
 render();
 if(route!=='map')window.scrollTo({top:0,behavior:'instant'});
}
navigate=go;
render=function(){
 document.title=`${routeName(page)} · AI Builder School`;
 document.body.classList.toggle('in-realm',page==='map');
 if(page==='map'){$('#app').innerHTML=realmPage();requestAnimationFrame(mountMap);return;}
 $('#app').innerHTML=shell();
 const type=page.split('/')[0],id=page.split('/')[1];
 const content=type==='week'?weekPage(Number(id)-1):type==='task'?taskPage(id):type==='submit'?submitPage(id):type==='work'?workPage(id):({home,resources:resourcesPage,gallery:communityPage,people:communityPage,profile:profilePage,friends:friendsPage,account:accountPage,login:loginPage}[page]||home)();
 $('#page-content').innerHTML=content;
 paintAll();
};
function syncRoute(){const route=location.hash.slice(1)||'home';if(route!==page)go(route,{fromHistory:true});}
window.addEventListener('popstate',syncRoute);window.addEventListener('hashchange',syncRoute);
function routeButton(route,label,cls='ghost'){return `<button class="${cls}" data-go="${route}">${label}</button>`;}
function taskCard(id){const t=taskCatalog[id],r=taskRecord(id);return `<article class="mission-card"><div class="mission-art"><img src="${expeditionAssets}navigation/${t.art}.webp" alt="" width="56" height="56"></div><div class="mission-body"><div class="mission-meta"><span>W1 · ${id==='site'?'01':'02'}</span><span class="status-chip ${r.versions.length?'submitted':''}">${taskState(id)}</span></div><h3>${t.title}</h3><p>${t.intro}</p><div class="mission-actions">${routeButton('task/'+id,'查看任务 ↗','text-link')}${routeButton((r.versions.length?'work/':'submit/')+id,r.versions.length?'查看提交':taskState(id)==='草稿'?'继续草稿':'记录第一版','primary')}</div></div></article>`;}
const homeBeforeExperience=home;
home=function(){let content=homeBeforeExperience();const start=content.indexOf('<article class="task-card">'),end=content.indexOf('<div class="section-head home-kit-heading">',start);if(start>=0&&end>=0)content=content.slice(0,start)+`<div class="mission-grid">${taskCard('site')}${taskCard('knowledge')}</div>`+content.slice(end);content=content.replace('做一个属于你的个人主页，<br>留下你想分享的故事。','做个人网站，建立个人知识库。<br>留下表达，也留下积累。').replace(/<span>WEEK 01<\/span><span>.*?<\/span>/,`<span>WEEK 01</span><span>已提交 ${submittedTasks()} / 2</span>`).replace(/<button class="primary" data-action="(mywork|submit|task)">.*? <svg[\s\S]*?<\/svg><\/button>/,`<button class="primary" data-go="week/1">查看本周两项任务 ${icon('arrow',15)}</button>`);return content;};
function weekPage(index){const w=weeks[index];return `<div class="route-line">${routeButton('map','← 返回旅程地图','text-link')}<span>CHAPTER ${String(index+1).padStart(2,'0')}</span></div>${title('',`W${index+1} · ${w[0]}`,w[2])}${index===0?`<div class="week-summary"><span>本周两项任务</span><strong>已提交 ${submittedTasks()} / 2</strong><span>W1 · 相识与表达</span></div><div class="mission-grid">${taskCard('site')}${taskCard('knowledge')}</div>`:`<section class="future-week"><span class="status-chip">未发布</span><h2>${w[1]}</h2><p>${journeyStops[index].deliverable}</p><div class="callout">本周任务尚未发布。请先完成当前周的任务。</div>${routeButton('week/1','查看当前 W1 任务','primary')}</section>`}`;}
function taskPage(id){const t=taskCatalog[id];return `<div class="route-line">${routeButton(taskOrigin,taskOrigin==='map'?'← 返回地图':'← W1 两项任务','text-link')}<span>WEEK 01</span></div>${title('',t.title,t.intro)}<div class="task-detail-layout"><section class="task-instructions"><h2>这次留下什么</h2><p>${t.deliverable}</p><h2>可以这样开始</h2><ol class="numbered-steps">${t.steps.map(s=>`<li>${s}</li>`).join('')}</ol><h2>提交前，自己看一遍</h2><ul class="task-checks">${t.checks.map(s=>`<li>${icon('check',16)}${s}</li>`).join('')}</ul><p class="form-note">提交前，请逐项核对以上内容。</p><a class="source-link" href="${t.source}" target="_blank" rel="noopener noreferrer">查看课程原文 ↗</a></section><aside class="task-side"><h2>配套锦囊</h2>${t.resources.map(r=>`<button class="lesson-shortcut" data-resource="${r}">${resources[r].title}<span>↗</span></button>`).join('')}<div class="task-state-box"><span class="status-chip">${taskState(id)}</span><p>${taskRecord(id).versions.length?`已保存 ${taskRecord(id).versions.length} 个版本，可以继续修改。`:'做出第一版，就先留下记录。'}</p>${routeButton('submit/'+id,taskRecord(id).versions.length?'提交修改版':taskState(id)==='草稿'?'继续草稿':'记录第一版','primary')}${taskRecord(id).versions.length?routeButton('work/'+id,'查看作品与反馈','text-link'):''}</div></aside></div>`;}
task=()=>go('week/1');week=i=>go('week/'+(i+1));submission=()=>go('submit/site');myWork=()=>go('work/site');
function submitPage(id){const t=taskCatalog[id],r=taskRecord(id),v=Object.keys(r.draft).length?r.draft:r.versions.at(-1)||{};return `<div class="route-line">${routeButton('task/'+id,'← 返回任务','text-link')}<span>${t.short}</span></div>${title('',r.versions.length?'留下一次修改':'记录你的第一版','草稿、提交和版本只保存在当前浏览器。')}<form id="mission-form" data-task="${id}" class="mission-form"><div class="field"><label for="mission-title">作品名称 *</label><input id="mission-title" name="title" required maxlength="60" value="${esc(v.title||'')}" placeholder="给你的${t.short}起个名字"></div><div class="field"><label for="mission-url">${id==='site'?'网站链接 *':'知识库或笔记链接（选填）'}</label><input id="mission-url" name="url" type="url" ${id==='site'?'required':''} value="${esc(v.url||'')}" placeholder="https://…"><p class="form-note">${id==='site'?'请先用另一台设备检查链接能否打开。':'不必公开完整知识库，填写整理成果说明即可。'}</p></div><div class="field"><label for="mission-description">${id==='site'?'介绍你的作品':'你整理了什么，准备怎样使用'} *</label><textarea id="mission-description" name="description" required maxlength="1000">${esc(v.description||'')}</textarea></div><div class="field"><label for="mission-question">希望伙伴帮你看什么（选填）</label><input id="mission-question" name="question" maxlength="200" value="${esc(v.question||'')}"></div>${r.versions.length?`<div class="field"><label for="mission-changes">这次改了什么 *</label><textarea id="mission-changes" name="changes" required maxlength="500">${esc(r.draft.changes||'')}</textarea></div>`:''}<p id="mission-error" class="error" role="alert"></p><div class="form-actions"><button class="primary" type="submit">保存第 ${r.versions.length+1} 版</button><button class="ghost" type="button" data-exp="save-mission">保存草稿</button></div><p class="form-note">这是本地提交演示，不会发给其他学员或助教。</p></form>`;}
function collectMission(){const form=$('#mission-form');return form?{id:form.dataset.task,data:Object.fromEntries(new FormData(form))}:null;}
function saveMission(draft=false){const result=collectMission();if(!result)return;const {id,data}=result,r=taskRecord(id);for(const key in data)data[key]=data[key].trim();if(!draft){if(!data.title||!data.description||(r.versions.length&&!data.changes)){$('#mission-error').textContent='请补齐作品名称、说明和本次修改。';return;}if((id==='site'||data.url)&&!safeLink(data.url)){$('#mission-error').textContent='请填写有效的 http:// 或 https:// 链接。';return;}}const ok=localSave(()=>{if(draft)r.draft=data;else{r.versions.push({...data,time:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})});r.draft={};}});if(ok){toast(draft?'草稿已保存到此浏览器':'这个版本已保存到此浏览器');if(!draft)go('work/'+id);}}
function workPage(id){const t=taskCatalog[id],r=taskRecord(id),v=r.versions.at(-1);if(!v)return `<div class="route-line">${routeButton('task/'+id,'← 返回任务','text-link')}</div><div class="empty"><h2>还没有提交${t.short}</h2>${routeButton('submit/'+id,'记录第一版','primary')}</div>`;const link=safeLink(v.url),feedback=r.feedback.filter(f=>f.work==='mine');return `<div class="route-line">${routeButton('profile','← 我的作品','text-link')}${routeButton('task/'+id,'查看任务 ↗','text-link')}</div>${title('',esc(v.title),`W1 · ${t.short} · v${r.versions.length}`)}<div class="work-detail"><section class="work-summary"><p>${esc(v.description)}</p>${link?`<a class="primary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">打开作品 ↗</a>`:''}${v.question?`<div class="callout">希望收到的建议：${esc(v.question)}</div>`:''}<div class="form-actions">${routeButton('submit/'+id,'提交修改版','ghost')}</div></section><section class="feedback-section"><div class="section-head"><h2>收到的反馈</h2><button class="text-link" data-exp="demo-task-feedback" data-task="${id}">体验一条模拟反馈</button></div>${feedback.map(f=>`<article class="feedback"><div class="author">${esc(f.author)} · 模拟反馈 <span class="version">针对 v${f.version}</span></div><p>${esc(f.text)}</p></article>`).join('')||'<p class="muted">目前还没有反馈。</p>'}</section><section class="version-history"><h2>修改记录</h2>${[...r.versions].reverse().map((it,i)=>`<div class="timeline-item"><strong>v${r.versions.length-i}</strong><div><p>${esc(it.changes||'保存第一版')}</p><small>${esc(it.time)}</small>${safeLink(it.url)?`<p><a href="${esc(safeLink(it.url))}" target="_blank" rel="noopener noreferrer">查看该版链接 ↗</a></p>`:''}</div></div>`).join('')}</section></div>`;}
// The prototype models sender/recipient consent; no real accounts or delivery service.
const memberIds=['self','achuan','lizi','xiaoman','asen','keke'];
if(saved.social?.version!==2){
 const legacy=Array.isArray(saved.friends)?[...new Set(saved.friends)].filter(id=>id!=='self'&&memberIds.includes(id)):[];
 saved.social={version:2,requests:legacy.map(id=>({id:'legacy-'+id,from:'self',to:id,status:'pending',createdAt:new Date().toISOString()}))};
}
saved.social.requests=Array.isArray(saved.social.requests)?saved.social.requests:[];
let friendsQuery='',personDialogId=null,friendViewer='self',friendsTab='accepted';
function communityMembers(){return people.map((p,i)=>({...p,id:memberIds[i],i,...(i===0?{name:saved.profile.name,bio:saved.profile.bio,help:saved.profile.help,tags:[saved.profile.help,saved.profile.need].filter(Boolean)}:{})}));}
const memberById=id=>communityMembers().find(p=>p.id===id);
const pairRequest=(id,viewer='self')=>saved.social.requests.findLast(r=>['pending','accepted'].includes(r.status)&&((r.from===viewer&&r.to===id)||(r.to===viewer&&r.from===id)));
const isFriend=(id,viewer='self')=>pairRequest(id,viewer)?.status==='accepted';
const friendIds=(viewer='self')=>memberIds.filter(id=>id!==viewer&&isFriend(id,viewer));
const incomingRequests=(viewer='self')=>saved.social.requests.filter(r=>r.to===viewer&&r.status==='pending');
const outgoingRequests=(viewer='self')=>saved.social.requests.filter(r=>r.from===viewer&&r.status==='pending');
function memberAction(p){
 if(p.id==='self')return '<span class="self-label">这是你</span>';
 const request=pairRequest(p.id);
 if(request?.status==='accepted')return `<span class="friend-status">${icon('check',14)} 已是好友</span>`;
 if(request?.status==='pending')return request.from==='self'?'<span class="friend-status pending">等待对方通过</span>':`<button class="ghost" data-friends-tab="received">查看好友申请</button>`;
 return `<button class="primary friend-add" data-friend-add="${p.id}" aria-label="加 ${esc(p.name)} 为好友">＋ 加好友</button>`;
}
function companionCard(p,{manage=false}={}){return `<article class="companion-card" data-member-id="${p.id}"><button class="companion-profile" data-person="${p.i}" aria-label="查看${esc(p.name)}的资料"><div class="companion-heading">${p.id==='self'?myAvatar():avatar(p.color)}<div><h3>${esc(p.name)}</h3><span>${p.id===friendViewer?'我的个人资料':'学习伙伴'}</span></div></div><p>${esc(p.bio)}</p><div class="tags">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></button><div class="companion-actions"><button class="text-link" data-person="${p.i}">查看资料 ↗</button>${manage?`<button class="text-link friend-remove" data-friend-remove="${p.id}" aria-label="移除好友 ${esc(p.name)}">移除好友</button>`:memberAction(p)}</div></article>`;}
function memberMatches(p,query){return [p.name,p.bio,p.help,...p.tags].join(' ').toLowerCase().includes(query.trim().toLowerCase());}
function originalPeople(){const list=communityMembers().filter(p=>memberMatches(p,peopleQuery));return `<div class="companions-toolbar"><label class="search">${icon('search',16)}<input id="people-search" aria-label="搜索伙伴姓名或兴趣" placeholder="找名字、兴趣或技能…" value="${esc(peopleQuery)}"></label>${routeButton('friends',`我的好友 <span class="friend-count">${friendIds().length}</span>`,'ghost')}</div><div class="companions-grid">${list.map(p=>companionCard(p)).join('')||'<div class="quiet-empty">暂时没有匹配的伙伴，换个名字或兴趣试试。</div>'}</div><p class="save-info">对方通过申请后，你们才会出现在彼此的好友列表。当前为本地流程演示，不会通知真实用户。</p>`;}
function friendsEntry(){const count=friendIds().length,pending=incomingRequests().length;return `<button class="friends-entry" data-go="friends"><img src="${expeditionAssets}navigation/05-companions.webp" alt="" width="48" height="48"><span><strong>我的好友</strong><small>${pending?`${pending} 条好友申请待处理`:count?`${count} 位伙伴，看看他们的介绍`:'查看好友与申请'}</small></span><span class="friend-count ${pending?'has-requests':''}">${pending||count}</span>${icon('chevron',18)}</button>`;}
function requestCard(r){
 const incoming=r.to===friendViewer,p=memberById(incoming?r.from:r.to);
 if(!p)return '';
 const status={pending:incoming?'想加你为好友':'等待对方通过',accepted:'已通过',declined:'未通过',cancelled:'已撤回',removed:'已解除好友关系'}[r.status]||'';
 return `<article class="request-card"><div class="companion-heading">${p.id==='self'?myAvatar():avatar(p.color)}<div><h3>${esc(p.name)}</h3><span>${status}</span></div></div><p>${esc(p.bio)}</p><div class="request-actions">${r.status==='pending'?(incoming?`<button class="primary" data-request-id="${r.id}" data-request-action="accepted">通过申请</button><button class="ghost" data-request-id="${r.id}" data-request-action="declined">暂不接受</button>`:`<button class="ghost" data-request-id="${r.id}" data-request-action="cancelled">撤回申请</button><button class="text-link demo-recipient" data-demo-recipient="${r.to}">演示：切换到${esc(p.name)}的收件箱 ↗</button>`):`<span class="status-chip">${status}</span>`}</div></article>`;
}
function friendsPage(){
 if(!saved.demoAccount.signedIn)return `<div class="route-line">${routeButton('profile','← 我的','text-link')}</div><section class="signed-out-card"><h1>我的好友</h1><p>进入体验账号，查看好友和申请。</p>${routeButton('login','体验登录流程','primary')}</section>`;
 const view=memberById(friendViewer),all=communityMembers().filter(p=>isFriend(p.id,friendViewer)),list=all.filter(p=>memberMatches(p,friendsQuery));
 const incoming=incomingRequests(friendViewer),outgoing=outgoingRequests(friendViewer);
 const requests=saved.social.requests.filter(r=>friendsTab==='received'?r.to===friendViewer:r.from===friendViewer).slice().reverse().filter((r,i,all)=>all.findIndex(other=>other.from===r.from&&other.to===r.to)===i);
 const demo=friendViewer!=='self'?`<div class="recipient-preview"><div><strong>正在演示：${esc(view.name)}的账户</strong><p>以下申请由收件人处理；你的真实资料没有切换。</p></div><button class="ghost" data-demo-recipient="self">返回我的视角</button></div>`:'';
 const accepted=all.length?`<div class="companions-toolbar"><label class="search">${icon('search',16)}<input id="friends-search" aria-label="搜索我的好友" placeholder="搜索好友名字或兴趣…" value="${esc(friendsQuery)}"></label></div><div class="companions-grid">${list.map(p=>companionCard(p,{manage:true})).join('')||'<div class="quiet-empty">没有找到这位好友，换个关键词试试。</div>'}</div>`:`<section class="friends-empty"><img src="${expeditionAssets}navigation/05-companions.webp" alt="" width="88" height="88"><h2>还没有通过的好友</h2><p>好友申请通过后，<br>你们才会出现在彼此的列表里。</p>${outgoing.length?`<button class="primary" data-friends-tab="sent">查看已发出的申请</button>`:incoming.length?`<button class="primary" data-friends-tab="received">查看收到的申请</button>`:routeButton('people','去认识伙伴','primary')}</section>`;
 return `<div class="route-line">${routeButton('profile','← 我的','text-link')}${routeButton('people','去广场认识伙伴 ↗','text-link')}</div>${demo}<div class="friends-heading"><div><h1>${friendViewer==='self'?'我的好友':esc(view.name)+'的好友'}</h1><p>相互确认，再开始同行。</p></div><span class="status-chip">${all.length} 位好友</span></div><div class="community-tabs friendship-tabs" role="tablist" aria-label="好友与申请">${[['accepted','好友',all.length],['received','收到的申请',incoming.length],['sent','发出的申请',outgoing.length]].map(([key,label,count])=>`<button role="tab" aria-selected="${friendsTab===key}" data-friends-tab="${key}">${label}${count?` <span>${count}</span>`:''}</button>`).join('')}</div><div role="tabpanel" aria-label="${friendsTab==='accepted'?'好友列表':friendsTab==='received'?'收到的申请':'发出的申请'}">${friendsTab==='accepted'?accepted:`<div class="request-list">${requests.map(requestCard).join('')||`<div class="quiet-empty">还没有${friendsTab==='received'?'收到':'发出'}好友申请。</div>`}</div>`}</div><p class="save-info">本地双向流程演示，不会通知真实用户，也不跨设备同步。暂不包含聊天。</p>`;
}
function personRelationship(p){if(friendViewer==='self'||page!=='friends')return p.id==='self'?'<button class="ghost" data-action="edit-profile">编辑资料</button>':memberAction(p);return isFriend(p.id,friendViewer)?'<span class="friend-status">已是好友</span>':'<span class="friend-status">尚未成为好友</span>';}
person=function(i){const p=communityMembers()[i];if(!p)return;personDialogId=p.id;openModal(`认识${esc(p.name)}`,`<div class="companion-heading">${p.id==='self'?myAvatar():avatar(p.color)}<div><h3>${esc(p.name)}</h3><span>伙伴资料</span></div></div><p class="companion-bio">${esc(p.bio)}</p><h3>可以一起聊聊</h3><div class="tags">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><h3>我能分享的经验</h3><p>${esc(p.help||'还没有填写。')}</p><div class="modal-actions">${personRelationship(p)}${routeButton('friends','查看好友与申请','ghost')}</div><p class="form-note">对方通过后才成为好友；当前为本地演示，不通知真实用户。</p>`,'伙伴资料');};
function refreshFriendViews(){const y=window.scrollY,dialog=$('#modal-root').querySelector('.modal')&&personDialogId;render();window.scrollTo({top:y,behavior:'instant'});if(dialog)person(memberIds.indexOf(dialog));}
function addFriend(id){
 if(!memberIds.includes(id)||id==='self'||pairRequest(id))return;
 if(!saved.demoAccount.signedIn){authStart();toast('先进入体验账号，再发送好友申请');return;}
 if(localSave(()=>saved.social.requests.push({id:crypto.randomUUID(),from:'self',to:id,status:'pending',createdAt:new Date().toISOString()}))){refreshFriendViews();toast('申请已记录，等待对方通过 · 本地演示');}
}
function updateFriendRequest(id,status){
 const r=saved.social.requests.find(r=>r.id===id);
 if(!saved.demoAccount.signedIn||!r||r.status!=='pending')return;
 const recipient=['accepted','declined'].includes(status)&&r.to===friendViewer;
 const sender=status==='cancelled'&&r.from===friendViewer;
 if(!recipient&&!sender)return;
 if(localSave(()=>{r.status=status;r.updatedAt=new Date().toISOString();})){render();toast({accepted:'已通过申请，你们现在是好友',declined:'已暂不接受这条申请',cancelled:'已撤回好友申请'}[status]+' · 本地演示');}
}
function confirmRemoveFriend(id){const p=memberById(id);if(!p||!isFriend(id,friendViewer))return;personDialogId=null;openModal('移除好友',`<p>将${esc(p.name)}从好友列表移除？再次添加需要重新发送申请，由对方通过。</p><div class="modal-actions"><button class="ghost" data-action="close">保留好友</button><button class="primary" data-friend-confirm-remove="${id}">确认移除</button></div>`,'我的好友');}
// Stable IDs keep likes attached to a work when filters or versions change.
works.forEach((w,i)=>Object.assign(w,[{id:'lizi-home',memberId:'lizi'},{id:'achuan-lab',memberId:'achuan'},{id:'xiaoman-portrait',memberId:'xiaoman'}][i]));
if(!saved.workLikes||typeof saved.workLikes!=='object'||Array.isArray(saved.workLikes))saved.workLikes={};
function workAuthor(p){return `<button class="author work-author" data-person="${p.i}" aria-label="查看${esc(p.name)}的资料">${p.id==='self'?myAvatar():avatar(p.color)}<span>${esc(p.name)}</span></button>`;}
function likeContents(key){const liked=saved.workLikes[key]===true;return `${icon('heart',17)}<span>${liked?'已赞':'点赞'}</span><span class="like-count">${liked?1:0}</span>`;}
function likeButton(key,title){return `<button class="work-like" data-like-key="${esc(key)}" data-like-title="${esc(title)}" aria-pressed="${saved.workLikes[key]===true}" aria-label="${saved.workLikes[key]===true?'取消点赞':'点赞'}《${esc(title)}》">${likeContents(key)}</button>`;}
function toggleWorkLike(key){
 const valid=works.some(w=>'example:'+w.id===key)||Object.keys(taskCatalog).some(id=>'own:'+id===key&&taskRecord(id).versions.length);
 if(!valid)return;
 if(!saved.demoAccount.signedIn){toast('先登录体验账号，再给作品点赞');return;}
 if(!localSave(()=>{if(saved.workLikes[key]===true)delete saved.workLikes[key];else saved.workLikes[key]=true;}))return;
 document.querySelectorAll('[data-like-key]').forEach(button=>{if(button.dataset.likeKey!==key)return;const liked=saved.workLikes[key]===true;button.innerHTML=likeContents(key);button.setAttribute('aria-pressed',String(liked));button.setAttribute('aria-label',`${liked?'取消点赞':'点赞'}《${button.dataset.likeTitle}》`);});
 toast(saved.workLikes[key]===true?'已点赞 · 保存在此浏览器':'已取消点赞');
}
workCard=function(w,i){const p=memberById(w.memberId);return `<article class="work-card social-work-card"><button class="work-open" data-work="${i}" aria-label="查看作品：${esc(w.title)}"><div class="work-cover"><canvas width="240" height="100" data-scene="${w.kind}" aria-hidden="true"></canvas><span class="cover-label">W1 · ${esc(w.type)}</span></div></button><div class="work-body"><button class="work-title" data-work="${i}"><h3>${esc(w.title)}</h3></button><div class="work-social-row">${workAuthor(p)}${likeButton('example:'+w.id,w.title)}</div></div></article>`;};
const workDetailBeforeSocial=workDetail;
workDetail=function(i){const w=works[i];if(!w)return;workDetailBeforeSocial(i);$('.modal-content').insertAdjacentHTML('afterbegin',`<div class="work-social-row detail-social-row">${workAuthor(memberById(w.memberId))}${likeButton('example:'+w.id,w.title)}</div>`);paintAll();};
function originalGallery(){
 const filters=['全部','个人网站','个人知识库','AI 画像'];
 const own=Object.entries(taskCatalog).filter(([id,t])=>taskRecord(id).versions.length&&(galleryFilter==='全部'||galleryFilter===t.short)).map(([id,t])=>{const r=taskRecord(id),v=r.versions.at(-1);return `<article class="work-card social-work-card"><button class="work-open" data-go="work/${id}" aria-label="查看作品：${esc(v.title)}"><div class="personal-work-cover"><img src="${expeditionAssets}navigation/${t.art}.webp" alt="" width="70" height="70"><span>${t.short}</span></div></button><div class="work-body"><button class="work-title" data-go="work/${id}"><h3>${esc(v.title)}</h3></button><div class="work-social-row">${workAuthor(memberById('self'))}${likeButton('own:'+id,v.title)}</div><p class="work-local-version">我的本地记录 · v${r.versions.length}</p></div></article>`;}).join('');
 const examples=works.map((w,i)=>({...w,i})).filter(w=>galleryFilter==='全部'||w.type===(galleryFilter==='个人网站'?'个人主页':galleryFilter)).map(w=>workCard(w,w.i)).join('');
 return `<div class="toolbar">${filters.map(f=>`<button class="filter ${galleryFilter===f?'active':''}" data-gallery-filter="${f}">${f}</button>`).join('')}</div><div class="gallery-grid">${own+examples||'<div class="quiet-empty">这里还没有作品。可以先从本周任务开始。</div>'}</div><p class="save-info">同学作品是虚构示例；你的记录只在本机显示，不会向其他人发布。</p>`;
}
function communityPage(){const members=page==='people';const contents=(members?originalPeople():originalGallery()).replace(/^<div class="page-title">[\s\S]*?<\/div><\/div>/,'');return `${title('','广场',members?'认识一起创造的人，找一个能聊起来的话题。':'看看大家在做什么，留下一条具体的建议。')}<div class="community-tabs" role="tablist" aria-label="广场内容"><button role="tab" aria-selected="${!members}" data-go="gallery">作品</button><button role="tab" aria-selected="${members}" data-go="people">伙伴</button></div><div role="tabpanel" aria-label="${members?'伙伴':'作品'}">${contents}</div>`;}
profilePage=function(){if(!saved.demoAccount.signedIn)return `<div class="personal-heading"><h1>我的</h1><span>你的学习档案</span></div><section class="signed-out-card"><span class="login-emblem">✦</span><h2>回来继续你的旅程</h2><p>登录后查看个人资料、作品和收到的反馈。</p>${routeButton('login','体验登录流程','primary')}<p class="form-note">这是本地账户演示。退出不会清除这个浏览器里的已有作品。</p></section>`;return `<div class="personal-heading"><div><span class="journey-eyebrow">YOUR SPACE</span><h1>我的</h1></div>${routeButton('account','账户设置 '+icon('settings',16),'ghost')}</div><section class="member-card"><button class="avatar-button" data-exp="avatar" aria-label="上传或更换头像">${myAvatar()}<span>更换头像</span></button><div class="member-intro"><span class="member-label">本地体验档案</span><h2>${esc(saved.profile.name)}</h2><p>${esc(saved.profile.bio)}</p><div class="tags"><span class="tag">第一期 · W1</span></div></div><button class="ghost edit-member" data-action="edit-profile">编辑资料</button></section>${friendsEntry()}<div class="personal-section-head"><h2>我的任务</h2><span>W1 · 已提交 ${submittedTasks()} / 2</span></div><div class="mission-grid">${taskCard('site')}${taskCard('knowledge')}</div><div class="personal-section-head"><h2>我的作品</h2><span>每个版本都留在这里</span></div><div class="personal-works">${Object.entries(taskCatalog).map(([id,t])=>{const r=taskRecord(id),v=r.versions.at(-1);return v?`<button class="personal-work" data-go="work/${id}"><div><small>${t.short} · v${r.versions.length}</small><h3>${esc(v.title)}</h3><p>${r.versions.length} 次提交 · ${r.feedback.filter(f=>f.work==='mine').length} 条反馈</p></div><span>↗</span></button>`:'';}).join('')||'<div class="quiet-empty">完成第一版后，你的作品和修改记录会出现在这里。</div>'}</div>`;};
editProfile=function(){if(!saved.demoAccount.signedIn){go('login');return;}openModal('编辑个人资料',`<form id="member-form"><div class="edit-avatar-row">${myAvatar()}<span class="form-note">头像可在个人中心点击更换</span></div><div class="field"><label for="member-name">希望大家怎么称呼你 *</label><input id="member-name" name="name" maxlength="20" required value="${esc(saved.profile.name)}"></div><div class="field"><label for="member-bio">简单介绍自己 *</label><textarea id="member-bio" name="bio" maxlength="200" required>${esc(saved.profile.bio)}</textarea></div><div class="field"><label for="member-help">愿意分享的经验</label><input id="member-help" name="help" maxlength="100" value="${esc(saved.profile.help)}"></div><div class="field"><label for="member-need">想找什么样的伙伴</label><input id="member-need" name="need" maxlength="100" value="${esc(saved.profile.need)}"></div><div class="form-actions"><button class="primary" type="submit">保存资料</button></div><p class="form-note">保存在当前浏览器，不会公开上传。</p></form>`,'个人资料');};
let cropImage=null,cropURL='',cropValues={zoom:1,x:50,y:50};
function avatarDialog(){if(!saved.demoAccount.signedIn){go('login');return;}cropImage=null;if(cropURL)URL.revokeObjectURL(cropURL);openModal('选一张喜欢的头像',`<div class="avatar-editor"><label class="upload-control" for="avatar-file">选择图片<input id="avatar-file" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="form-note">JPG、PNG 或 WebP，最大 8 MB；图片只在本机处理。</p><p id="avatar-error" class="error" role="alert"></p><div id="crop-controls" hidden><canvas id="avatar-crop" width="256" height="256" aria-label="头像裁剪预览"></canvas><label>放大 <input id="crop-zoom" type="range" min="1" max="3" step="0.05" value="1"></label><label>左右 <input id="crop-x" type="range" min="0" max="100" value="50"></label><label>上下 <input id="crop-y" type="range" min="0" max="100" value="50"></label><button class="primary" data-exp="save-avatar">使用这张头像</button></div>${saved.profile.avatar?'<button class="text-link" data-exp="remove-avatar">恢复默认头像</button>':''}</div>`,'上传与裁剪');}
function paintCrop(){const c=$('#avatar-crop');if(!c||!cropImage)return;const ctx=c.getContext('2d'),side=Math.min(cropImage.naturalWidth,cropImage.naturalHeight)/cropValues.zoom;ctx.clearRect(0,0,256,256);ctx.drawImage(cropImage,(cropImage.naturalWidth-side)*cropValues.x/100,(cropImage.naturalHeight-side)*cropValues.y/100,side,side,0,0,256,256);}
async function loadAvatar(file){const error=$('#avatar-error');if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024){error.textContent='请选择不超过 8 MB 的 JPG、PNG 或 WebP 图片。';return;}error.textContent='';cropImage=null;$('#crop-controls').hidden=true;if(cropURL)URL.revokeObjectURL(cropURL);const url=URL.createObjectURL(file);cropURL=url;const img=new Image();try{img.src=url;await img.decode();if(!$('#avatar-crop')||url!==cropURL)return;if(img.naturalWidth*img.naturalHeight>40000000)throw Error();cropImage=img;cropValues={zoom:1,x:50,y:50};$('#crop-zoom').value=1;$('#crop-x').value=50;$('#crop-y').value=50;$('#crop-controls').hidden=false;paintCrop();}catch{if($('#avatar-error'))$('#avatar-error').textContent='无法读取这张图片，请换一张较小的图片。';}}
const maskIdentity=(channel,value)=>channel==='phone'?value.slice(0,3)+' **** '+value.slice(-4):value.replace(/^(.{1,2}).*?@/,'$1***@');
let authFlow={intent:'login',channel:'phone',issuedFor:'',back:'profile'};
function authStart(intent='login',channel='phone'){authFlow={intent,channel,issuedFor:'',back:intent==='bind'?'account':'profile'};go('login');}
function loginPage(){const email=authFlow.channel==='email';return `<div class="route-line">${routeButton(authFlow.back,'← 返回','text-link')}</div><section class="auth-card"><span class="member-label">账户流程演示</span><h1>${authFlow.intent==='bind'?'绑定登录方式':'欢迎回来'}</h1><p>用同一个体验档案继续查看作品。</p><div class="community-tabs" role="tablist" aria-label="登录方式"><button type="button" role="tab" aria-selected="${!email}" data-auth-channel="phone">手机号</button><button type="button" role="tab" aria-selected="${email}" data-auth-channel="email">邮箱</button></div><form id="demo-auth-form"><div class="field"><label for="auth-identity">${email?'测试邮箱':'测试手机号（+86）'}</label><input id="auth-identity" name="identity" type="${email?'email':'tel'}" autocomplete="off" required value="${email?'student@example.com':'13800000000'}" ${email?'':'inputmode="tel" pattern="1[3-9][0-9]{9}"'}></div><div class="field"><label for="auth-code">演示验证码</label><div class="code-field"><input id="auth-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"><button type="button" class="ghost" data-exp="demo-code">获取演示码</button></div></div><p id="auth-notice" role="status" class="auth-notice">不会发送短信或邮件。请使用预填测试信息体验。</p><p id="auth-error" class="error" role="alert"></p><button class="primary" type="submit">${authFlow.intent==='bind'?'确认模拟绑定':'进入体验账号'}</button></form><p class="form-note">这是界面演示，不验证真实身份。真实登录和跨设备同步尚未接入。</p></section>`;}
function accountPage(){if(!saved.demoAccount.signedIn)return profilePage();return `<div class="route-line">${routeButton('profile','← 我的','text-link')}</div>${title('','账户设置','管理这个体验档案的登录方式。')}<section class="account-panel"><div class="account-summary">${myAvatar()}<div><h2>${esc(saved.profile.name)}</h2><p>本地体验账号 · 非真实认证</p></div></div>${['phone','email'].map(channel=>`<div class="account-row"><div><strong>${channel==='phone'?'手机号':'邮箱'}</strong><p>${saved.demoAccount[channel]?esc(maskIdentity(channel,saved.demoAccount[channel]))+' · 模拟绑定':'尚未绑定'}</p></div><button class="ghost" data-bind="${channel}">${saved.demoAccount[channel]?'更换':'绑定'}</button></div>`).join('')}<div class="quiet-note">两种登录方式指向同一份体验档案。这里只演示绑定流程，不会向真实号码或邮箱发送验证码。</div><button class="logout-button" data-exp="logout">退出体验账号</button></section>`;}
function finishAuth(e){e.preventDefault();const form=e.target,value=form.elements.identity.value.trim();if(value!==authFlow.issuedFor||form.elements.code.value!=='123456'){$('#auth-error').textContent='请先获取此测试账号的演示码，再填写显示的 6 位数字。';return;}if(localSave(()=>{saved.demoAccount[authFlow.channel]=value;saved.demoAccount.signedIn=true;})){go(authFlow.intent==='bind'?'account':'profile');toast(authFlow.intent==='bind'?'已保存模拟绑定':'已进入本地体验账号');}}
// All new actions use a separate namespace so legacy lesson modals keep working.
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.likeKey){toggleWorkLike(b.dataset.likeKey);return;}
 if(b.dataset.friendAdd){addFriend(b.dataset.friendAdd);return;}
 if(b.dataset.friendRemove){confirmRemoveFriend(b.dataset.friendRemove);return;}
 if(b.dataset.friendsTab){friendsTab=b.dataset.friendsTab;if(page==='friends'){closeModal();render();}else go('friends');return;}
 if(b.dataset.demoRecipient){const id=b.dataset.demoRecipient;if(memberIds.includes(id)){friendViewer=id;friendsTab=id==='self'?'sent':'received';friendsQuery='';closeModal();render();}return;}
 if(b.dataset.requestAction){updateFriendRequest(b.dataset.requestId,b.dataset.requestAction);return;}
 if(b.dataset.friendConfirmRemove){const id=b.dataset.friendConfirmRemove,r=pairRequest(id,friendViewer);if(saved.demoAccount.signedIn&&r?.status==='accepted'&&localSave(()=>{r.status='removed';r.updatedAt=new Date().toISOString();})){closeModal();render();toast('已解除好友关系，再次添加需要重新申请');}return;}
 if(b.dataset.go){if(b.dataset.go==='login')authFlow={intent:'login',channel:'phone',issuedFor:'',back:'profile'};go(b.dataset.go);return;}
 if(b.dataset.authChannel){authFlow.channel=b.dataset.authChannel;authFlow.issuedFor='';render();return;}
 if(b.dataset.bind){authStart('bind',b.dataset.bind);return;}
 const action=b.dataset.exp;
 if(action==='avatar')avatarDialog();
 if(action==='save-avatar'&&cropImage){const data=$('#avatar-crop').toDataURL('image/webp',.88);if(localSave(()=>saved.profile.avatar=data)){closeModal();render();toast('头像已保存在本机');}}
 if(action==='remove-avatar'&&localSave(()=>delete saved.profile.avatar)){closeModal();render();}
 if(action==='save-mission')saveMission(true);
 if(action==='demo-task-feedback'){const id=b.dataset.task,r=taskRecord(id);if(!r.feedback.some(f=>f.work==='mine'&&f.version===r.versions.length)){if(localSave(()=>r.feedback.push({work:'mine',version:r.versions.length,author:'示例伙伴',demo:true,text:id==='site'?'介绍里的具体经历很容易记住。可以再补一个正在做的小项目，让伙伴知道能一起做什么。':'按主题整理之后更容易找了。建议把每条笔记的来源和日期补齐，下一次回看更方便。'})))render();}else toast('这一版已有一条模拟反馈');}
 if(action==='demo-code'){const input=$('#auth-identity');if(!input.reportValidity())return;authFlow.issuedFor=input.value.trim();$('#auth-notice').textContent='演示码：123456（没有发送短信或邮件）';$('#auth-error').textContent='';$('#auth-code').focus();}
 if(action==='logout'&&localSave(()=>saved.demoAccount.signedIn=false)){go('profile');toast('已退出体验账号，原有作品仍保留在此浏览器');}
});
document.addEventListener('submit',e=>{if(e.target.id==='mission-form'){e.preventDefault();saveMission();}if(e.target.id==='demo-auth-form')finishAuth(e);if(e.target.id==='member-form'){e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k in values)values[k]=values[k].trim();if(!values.name||!values.bio)return;if(localSave(()=>saved.profile={...saved.profile,...values})){closeModal();render();toast('资料已保存');}}});
document.addEventListener('change',e=>{if(e.target.id==='avatar-file')loadAvatar(e.target.files[0]);});
document.addEventListener('input',e=>{if(e.target.id.startsWith('crop-')){const key=e.target.id.slice(5);cropValues[key]=Number(e.target.value);paintCrop();}});
document.addEventListener('input',e=>{if(e.target.id==='friends-search'){const pos=e.target.selectionStart;friendsQuery=e.target.value;render();const input=$('#friends-search');input.focus();input.setSelectionRange(pos,pos);}});
