review=function(){openModal('使用说明',`<h3>完成本周任务</h3><p>在冒险大厅查看两项任务，按任务要求制作作品，打开配套锦囊查找方法。</p><h3>记录作品与修改</h3><p>填写作品说明和链接，保存草稿或提交版本。在个人中心回看作品、反馈和修改记录。</p><h3>认识伙伴</h3><p>在广场查看伙伴资料与作品，给作品点赞或留下具体建议。</p><div class="callout">当前为体验版本。作品、资料和互动记录保存在当前浏览器；登录、好友申请和同伴反馈为模拟流程，不会向其他人发送消息。</div><div class="modal-actions"><button class="primary" data-action="task">查看本周任务</button></div>`,'AI Builder School');};
